func outcomeByPath(outcomes []FileOutcome) map[string]FileOutcomeKind {
	m := make(map[string]FileOutcomeKind, len(outcomes))
	for _, o := range outcomes {
		m[o.Path] = o.Outcome
	}
	return m
}

